const char * tool_diag_ct_diag_code_for_error(const char * msg) {
    if (strstr(msg, "unexpected token")) {
        return "E-PARSE-001";
    }
    if (strstr(msg, "expected an expression")) {
        return "E-PARSE-002";
    }
    if (strstr(msg, "use of an undeclared variable")) {
        return "E-PARSE-004";
    }
    if (strstr(msg, "a defer block cannot transfer control")) {
        return "E-PARSE-006";
    }
    if (strstr(msg, "an errdefer block cannot transfer control")) {
        return "E-PARSE-007";
    }
    if (strstr(msg, "break is only allowed in a loop or switch")) {
        return "E-PARSE-008";
    }
    if (strstr(msg, "continue is only allowed in a loop")) {
        return "E-PARSE-009";
    }
    if (strstr(msg, "unreachable code after a jump")) {
        return "E-PARSE-010";
    }
    if (strstr(msg, "auto-drop requires the closing")) {
        return "E-PARSE-011";
    }
    if (strstr(msg, "a goto cannot cross a block with defer")) {
        return "E-PARSE-012";
    }
    if (strstr(msg, "an own object cannot be rolled back by errdefer")) {
        return "E-PARSE-013";
    }
    if (strstr(msg, "a closure cannot escape through 'return'")) {
        return "E-PARSE-014";
    }
    if (strstr(msg, "cannot resolve import")) {
        return "E-DRIVER-001";
    }
    if (strstr(msg, "cannot open the input file")) {
        return "E-DRIVER-002";
    }
    if (strstr(msg, "a .m.ct unit produces no output")) {
        return "E-DRIVER-003";
    }
    if (strstr(msg, "cannot write the output file")) {
        return "E-DRIVER-004";
    }
    if (strstr(msg, "a method call on a temporary")) {
        return "E-LOWER-001";
    }
    if (strstr(msg, "too many hoisted receivers")) {
        return "E-LOWER-002";
    }
    if (strstr(msg, "lowering invariant I1")) {
        return "E-LOWER-004";
    }
    if (strstr(msg, "lowering invariant I2")) {
        return "E-LOWER-005";
    }
    if (strstr(msg, "lowering invariant I3")) {
        return "E-LOWER-006";
    }
    if (strstr(msg, "lowering invariant I4")) {
        return "E-LOWER-007";
    }
    if (strstr(msg, "type mismatch")) {
        return "W-TYPE-002";
    }
    if (strstr(msg, "arity mismatch")) {
        return "W-TYPE-001";
    }
    if (strstr(msg, "ambiguous method")) {
        return "W-TRAIT-001";
    }
    if (strstr(msg, "signature mismatch")) {
        return "W-TRAIT-002";
    }
    return "";
}
const char * tool_diag_ct_diag_warn_code(int kind) {
    if (kind == 0) {
        return "W-MEM-001";
    }
    if (kind == 1) {
        return "W-TRAIT-002";
    }
    if (kind == 2) {
        return "W-MEM-002";
    }
    if (kind == 3) {
        return "W-MEM-003";
    }
    if (kind == 4) {
        return "W-TYPE-001";
    }
    if (kind == 5) {
        return "W-TYPE-002";
    }
    if (kind == 6) {
        return "W-TRAIT-001";
    }
    if (kind == 7) {
        return "W-NAME-001";
    }
    if (kind == 8) {
        return "W-DRIVER-001";
    }
    if (kind == 9) {
        return "W-MEM-004";
    }
    if (kind == 10) {
        return "W-MEM-005";
    }
    if (kind == 11) {
        return "W-MEM-006";
    }
    if (kind == 12) {
        return "W-LANG-001";
    }
    return "";
}
