int tool_diag_ct_diag_leaks_failed(void) {
    int i;
    if ((!tool_diag_g_diag.leaks_error)) {
        return 0;
    }
    for (i = 0; i < tool_diag_g_diag.nwarns; i++) {
        int k = tool_diag_g_diag.warns[i].kind;
        if ((((k == 0) || (k == 2)) || (k == 10))) {
            return 1;
        }
    }
    return 0;
}
